content:
.site-page, .site-auth-main { overflow: clip; }
.site-page .container, .site-header .container, .site-footer .container { width: min(1360px, calc(100% - 40px)); }
.site-page section[id] { scroll-margin-top: 78px; }
.site-section { padding-block: clamp(76px, 10vw, 140px); }
.site-section-heading { display: flex; align-items: end; justify-content: space-between; gap: 28px; margin-bottom: 36px; }
.site-section-heading > div { max-width: 720px; }
.site-section-heading h2, .site-story h2, .site-purpose h2, .site-team h2, .site-contact h2, .site-timeline-section h2 { font-size: clamp(32px, 5vw, 66px); font-weight: 800; line-height: 1.06; letter-spacing: -0.065em; }
.site-section-heading p:not(.eyebrow), .site-story-grid p:not(.eyebrow), .site-team-grid > div:first-child > p:not(.eyebrow), .site-contact-grid p:not(.eyebrow) { color: var(--text); font-size: clamp(14px, 1.4vw, 17px); margin-top: 18px; }
.site-empty { min-height: 230px; display: grid; place-content: center; justify-items: center; gap: 14px; padding: 36px; border: 1px solid var(--line); border-radius: var(--radius); color: var(--text); text-align: center; }

.site-header { position: fixed; inset: 0 0 auto; z-index: 70; isolation: isolate; color: white; background: transparent; }
.site-header::before { content: ""; position: absolute; inset: 0; z-index: -1; pointer-events: none; background: var(--ink); box-shadow: 0 12px 30px rgb(6 33 41 / .17); opacity: 0; transition: opacity var(--dur-base) var(--ease-out); }
.site-header.is-solid::before { opacity: 1; }
.site-header-inner { min-height: 76px; display: flex; align-items: center; gap: 28px; }
.site-logo { display: flex; flex: 0 0 auto; align-items: center; }
.site-logo img { width: 163px; height: auto; }
.site-header a:hover { color: var(--lime); }
.site-header :focus-visible { outline-color: var(--lime); }
.site-nav { position: relative; display: none; align-items: center; gap: clamp(14px, 1.55vw, 26px); margin-left: auto; }
.site-nav a { position: relative; font-size: 11px; font-weight: 700; white-space: nowrap; transition: color 260ms var(--ease-out); }
.site-nav a[aria-current] { color: var(--lime); }
.site-nav a::after { content: ""; position: absolute; inset: auto 0 -10px; height: 2px; background: var(--lime); transform: scaleX(0); transform-origin: left; transition: transform var(--dur-base) var(--ease-out); }
.site-nav a:hover::after, .site-nav a[aria-current]::after { transform: scaleX(1); }
.site-nav[data-indicator-ready] a[aria-current]::after { transform: scaleX(0); }
.site-nav-indicator { position: absolute; left: 0; bottom: -10px; width: var(--site-nav-indicator-width, 0px); height: 3px; border-radius: 3px; background: var(--lime); box-shadow: 0 0 10px rgb(198 223 35 / .35); opacity: var(--site-nav-indicator-opacity, 0); transform: translateX(var(--site-nav-indicator-x, 0px)); pointer-events: none; transition: transform 340ms var(--ease-out), width 340ms var(--ease-out), opacity 180ms ease; }
.site-header-actions { display: none; align-items: center; gap: 12px; }
.site-header-actions .button { min-height: 42px; padding-inline: 15px; white-space: nowrap; }
.site-login { font-size: 12px; font-weight: 750; padding: 10px; white-space: nowrap; }
.site-login svg { display: none; }
.site-header .button.lime:hover { color: var(--ink); background: #c4da30; }
.site-menu-button { margin-left: auto; color: white; }
.site-menu-button:hover { background: var(--on-ink-line); }
.site-mobile-nav { display: grid; gap: 2px; padding-block: 8px 24px; }
.site-mobile-nav > a:not(.button) { display: block; padding: 12px 4px; font-size: 16px; font-weight: 700; border-bottom: 1px solid var(--line); }
.site-mobile-nav > a[aria-current] { color: var(--lime-text); }
.site-mobile-nav .button { margin-top: 15px; }
.site-access-frame { display: flex; flex-direction: column; min-height: 100svh; }
.site-access-frame > .site-auth-main { flex: 1; }
.site-access-frame > .site-footer { flex-shrink: 0; }
.site-auth-main { padding-top: 76px; min-height: 70vh; }
.site-session-check, .session-gate { min-height: 100svh; display: grid; place-content: center; justify-items: center; gap: 22px; background: var(--ink); color: white; font-weight: 750; }
.site-session-check { position: fixed; inset: 0; z-index: 90; }
.session-gate > [role="status"] { animation: session-gate-wait 240ms ease 1200ms both; }
@keyframes session-gate-wait { from { opacity: 0; } }

.site-hero { min-height: 100svh; position: relative; isolation: isolate; overflow: hidden; display: flex; align-items: center; background: var(--ink); color: white; }
.site-hero-grain { position: absolute; inset: 0; opacity: .18; background: radial-gradient(circle at 10% 85%, rgb(255 255 255 / .12), transparent 32%); mask-image: linear-gradient(to bottom, black 0%, black 78%, transparent 100%); pointer-events: none; }
.site-hero-grid { position: relative; z-index: 1; display: grid; gap: 18px; width: 100%; padding-top: 112px; padding-bottom: 64px; }
.site-hero-copy { position: relative; z-index: 2; }
.site-hero-copy .eyebrow { color: var(--lime); }
.site-hero h1 { font-size: clamp(43px, 10.2vw, 76px); font-weight: 800; line-height: 1.015; letter-spacing: -.072em; max-width: 830px; }
.site-hero h1 span { display: block; }
.site-hero-lead { color: var(--on-ink-muted); max-width: 530px; font-size: clamp(14px, 1.4vw, 17px); line-height: 1.65; margin-top: 21px; }
.site-hero .actions { align-items: stretch; margin-top: 27px; }
.site-button-large { min-height: 52px; padding: 14px 23px; font-size: 13px; border-radius: 7px; }
.site-button-outline { border-color: rgb(255 255 255 / .44); color: white; background: transparent; }
.site-button-outline:hover { border-color: var(--lime); background: rgb(255 255 255 / .06); }
.site-hero-visual { position: relative; width: min(100%, 520px); min-height: 250px; aspect-ratio: 1.33; margin: 8px auto 0; }

.site-brands { overflow: hidden; background: white; }
.site-brands-intro { display: grid; gap: 20px; align-items: end; margin-bottom: clamp(30px, 4vw, 50px); }
.site-brands-intro .eyebrow { margin-bottom: 8px; color: var(--ink); }
.site-brands-intro h2 { max-width: 750px; min-height: 2.12em; font-size: clamp(34px, 4.4vw, 60px); font-weight: 800; line-height: 1.06; letter-spacing: -.065em; }
.site-brands-intro > p { max-width: 510px; color: var(--text); font-size: clamp(15px, 1.25vw, 18px); line-height: 1.65; }
.site-brands-stage { position: relative; }
.site-brands-rail { display: flex; gap: 10px; overflow-x: auto; overflow-y: hidden; padding-bottom: 4px; scroll-snap-type: x mandatory; overscroll-behavior-inline: contain; scrollbar-width: none; }
.site-brands-rail::-webkit-scrollbar { display: none; }
.site-brand-card, .site-brands-loading > span { flex: 0 0 clamp(180px, 13vw, 205px); width: clamp(180px, 13vw, 205px); height: clamp(335px, 29vw, 410px); border-radius: 14px; }
.site-brand-card { position: relative; isolation: isolate; display: block; overflow: hidden; scroll-snap-align: start; background: var(--card-color); color: white; }
.site-brand-card--ink { --card-color: #74525a; }
.site-brand-card--moss { --card-color: #425e55; }
.site-brand-card--slate { --card-color: #6480a5; }
.site-brand-card--clay { --card-color: #b87555; }
.site-brand-card--lime { --card-color: #a9b96b; }
.site-brand-card--earth { --card-color: #957052; }
.site-brand-card--rose { --card-color: #b97b7e; }
.site-brand-card--leaf { --card-color: #88a850; }
.site-brand-art { position: absolute; inset: 0; display: grid; place-items: center; overflow: hidden; }
.site-brand-art > img { position: absolute; inset: 0; width: 100%; height: 100%; object-fit: cover; mix-blend-mode: multiply; opacity: 0; }
.site-brand-art.is-loaded > img { opacity: .76; }
.site-brand-art .brand-mark { width: 76%; height: 35%; opacity: .88; }
.site-brand-art.is-loaded .brand-mark { opacity: 0; }
.site-brand-art .brand-mark img { object-fit: contain; }
.site-brand-art .brand-mark--text { display: grid; place-items: center; color: rgb(255 255 255 / .7); font-size: 28px; font-weight: 850; line-height: 1; text-align: center; text-transform: uppercase; }
.site-brand-card::after { content: ""; position: absolute; inset: 28% 0 0; z-index: 0; pointer-events: none; background: linear-gradient(transparent 5%, rgb(7 29 36 / .08) 34%, rgb(4 20 26 / .68) 100%); }
.site-brand-card-copy { position: absolute; z-index: 1; inset: auto 18px 19px; display: grid; gap: 3px; text-align: center; text-transform: uppercase; }
.site-brand-card-copy strong { font-size: 14px; font-weight: 850; line-height: 1.3; text-wrap: balance; }
.site-brand-card-copy small { min-height: 17px; color: rgb(255 255 255 / .83); font-size: 10px; font-weight: 800; letter-spacing: .12em; }
.site-brand-card-corner { position: absolute; z-index: 1; top: 14px; right: 14px; display: grid; place-items: center; width: 32px; height: 32px; border: 1px solid rgb(255 255 255 / .5); border-radius: 50%; background: rgb(5 33 43 / .25); }
.site-brand-card:hover { color: white; }
.site-brands-arrow { position: absolute; top: 50%; z-index: 2; display: grid; place-items: center; width: 44px; height: 44px; border: 0; border-radius: 50%; background: white; color: var(--ink); box-shadow: 0 8px 24px rgb(4 29 37 / .18); transform: translateY(-50%); }
.site-brands-arrow--previous { left: 8px; }
.site-brands-arrow--next { right: 8px; }
.site-brands-arrow:disabled { opacity: .5; }
.site-brands-footer { display: grid; gap: clamp(28px, 4vw, 50px); padding-top: 18px; }
.site-brands-dots { display: flex; justify-content: center; align-items: center; gap: 9px; min-height: 18px; }
.site-brands-dots button { width: 8px; height: 8px; padding: 0; border: 0; border-radius: 8px; background: #9ca7a8; }
.site-brands-dots button.is-active { width: 27px; background: var(--ink); }
.site-brands-page { margin: 0; text-align: center; color: var(--text); font-size: 12px; font-weight: 750; letter-spacing: .12em; }
.site-brands-actions { display: flex; flex-wrap: wrap; gap: 12px; }
.site-brands-actions .button { min-height: 48px; padding-inline: 25px; }
.site-brands-loading { overflow: hidden; }
.site-brands-loading > span { display: block; background: var(--paper); }
.site-brands-footer-loading > span { justify-self: center; width: 66px; height: 8px; margin-block: 5px; border-radius: 5px; background: var(--paper); }
.site-brands-footer-loading > div { display: flex; gap: 12px; }
.site-brands-footer-loading > div span { display: block; width: 210px; height: 48px; border-radius: 7px; background: var(--paper); }

.site-story-grid { display: grid; gap: 34px; align-items: center; }
.site-story-grid > div:first-child { max-width: 680px; }
.site-story-grid > div:first-child p:not(.eyebrow) { max-width: 610px; }
.site-story-media { position: relative; aspect-ratio: 1.25; border-radius: var(--radius); overflow: hidden; background: var(--paper); }
.site-story-media img { width: 100%; height: 100%; object-fit: cover; }
.site-story-media > span { position: absolute; right: 0; bottom: 0; padding: 18px 22px; background: var(--lime); color: var(--ink); font-size: 12px; line-height: 1.25; }
.site-story-media strong { display: block; font-size: 16px; }
.site-facts { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 26px; margin-top: 60px; padding-top: 34px; border-top: 1px solid var(--line); }
.site-facts div { display: grid; align-content: start; gap: 8px; }
.site-facts span:first-child { font-size: 11px; color: var(--text); text-transform: uppercase; letter-spacing: .12em; }
.site-facts strong { font-size: clamp(28px, 4vw, 50px); line-height: 1.1; font-weight: 800; letter-spacing: -.06em; }

.site-purpose { max-width: 1600px; margin-inline: auto; }
.site-purpose-row { display: grid; background: white; }
.site-purpose-image { aspect-ratio: 1.3; overflow: hidden; background: var(--paper); }
.site-purpose-image img { width: 100%; height: 100%; object-fit: cover; }
.site-purpose-copy { display: grid; align-content: center; min-height: 310px; padding: clamp(28px, 6vw, 90px) max(20px, calc((100vw - 1360px) / 2)); }
.site-purpose-copy .eyebrow { color: var(--lime-text); }
.site-purpose-copy h2 { margin-bottom: 20px; }
.site-purpose-copy p:not(.eyebrow) { max-width: 560px; color: var(--text); font-size: clamp(15px, 1.4vw, 18px); }
.site-purpose-copy strong { color: var(--ink); font-weight: 800; }
.site-values { display: flex; flex-wrap: wrap; gap: 6px 13px; max-width: 650px; line-height: 1.25; }
.site-values span { color: var(--lime-text); font-weight: 800; font-size: clamp(18px, 2.2vw, 30px); }
.site-values span:nth-child(2) { color: var(--ink); font-size: clamp(23px, 3vw, 40px); }
.site-values span:nth-child(3) { font-size: clamp(20px, 2.6vw, 35px); }
.site-values span:nth-child(4) { color: var(--ink); font-size: clamp(17px, 1.8vw, 24px); }


.site-featured { background: white; }
.site-product-grid { display: grid; grid-template-columns: repeat(2, minmax(0, 1fr)); gap: 16px; }
.site-product-card { min-width: 0; border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; background: white; }
.site-product-image { position: relative; display: grid; place-items: center; aspect-ratio: 1 / 1.05; overflow: hidden; border-bottom: 1px solid var(--line); background: white; }
.site-product-image img { width: 100%; height: 100%; object-fit: contain; padding: 16px; }
.site-product-badge { position: absolute; top: 12px; left: 12px; background: var(--lime); color: var(--ink); padding: 4px 9px; border-radius: 40px; font-size: 10px; font-weight: 750; }
.site-product-copy { padding: 15px; }
.site-product-copy .eyebrow { color: var(--lime-text); font-size: 13px; margin-bottom: 6px; }
.site-product-copy h3 { font-size: 14px; line-height: 1.3; min-height: 2.6em; margin-bottom: 14px; }
.site-product-copy .text-link { font-size: 11px; }
.site-product-skeleton .site-product-copy { display: grid; gap: 10px; }
.site-product-skeleton .site-product-copy span { height: 12px; width: 90%; background: var(--paper); border-radius: 4px; }
.site-product-skeleton .site-product-copy span:last-child { width: 55%; }
.site-featured-cta { display: flex; justify-content: space-between; gap: 18px; flex-wrap: wrap; margin-top: 28px; padding-top: 20px; border-top: 1px solid var(--line); color: var(--text); font-size: 13px; }

.site-process { background: var(--ink); color: white; }
.site-process .site-section-heading p:not(.eyebrow) { color: var(--on-ink-muted); }
.site-process .eyebrow { color: var(--lime); }
.site-steps { display: grid; grid-template-columns: 1fr; gap: 12px; margin: 0 0 30px; padding: 0; list-style: none; }
.site-steps li { position: relative; display: grid; grid-template-columns: 38px 1fr; align-items: start; gap: 7px 13px; min-height: 130px; padding: 23px; border: 1px solid var(--on-ink-line); border-radius: 14px; background: rgb(255 255 255 / .045); }
.site-steps li > svg { color: var(--lime); grid-column: 1; grid-row: 2 / 4; }
.site-step-number { grid-column: 1 / -1; color: var(--on-ink-muted); font-size: 10px; letter-spacing: .16em; }
.site-steps h3 { grid-column: 2; font-size: 17px; }
.site-steps p { grid-column: 2; color: var(--on-ink-muted); font-size: 12px; }
.site-process .button.lime { background: var(--lime); color: var(--ink); }

.site-operation-grid { display: grid; gap: 18px; }
.site-operation-photo { position: relative; min-height: 410px; border-radius: var(--radius); overflow: hidden; background: var(--paper); color: white; }
.site-operation-photo > img { width: 100%; height: 100%; object-fit: cover; position: absolute; inset: 0; }
.site-operation-photo::after { content: ""; position: absolute; inset: 40% 0 0; background: linear-gradient(transparent, rgb(9 39 49 / .86)); }
.site-operation-photo > div { position: absolute; z-index: 1; inset: auto 20px 22px; display: grid; gap: 7px; }
.site-operation-photo strong { font-size: 22px; line-height: 1.2; }
.site-operation-photo span { max-width: 490px; color: var(--on-ink-muted); font-size: 13px; }
.site-operation-cards { display: grid; gap: 12px; }
.site-operation-cards article { min-height: 155px; padding: 22px; border-radius: 14px; background: var(--paper); }
.site-operation-cards svg { color: var(--lime-text); margin-bottom: 9px; }
.site-operation-cards h3 { font-size: 18px; margin-bottom: 8px; }
.site-operation-cards p { color: var(--text); font-size: 12px; }

.site-timeline-section { background: var(--paper); }
.site-timeline-section h2 { max-width: 730px; }
.site-timeline { position: relative; display: grid; gap: 0; margin: 48px 0 0; padding: 0 0 0 34px; list-style: none; }
.site-timeline::before, .site-timeline::after { content: ""; position: absolute; top: 0; bottom: 0; left: 6px; width: 3px; border-radius: 4px; background: var(--line); }
.site-timeline::after { background: var(--lime); transform: scaleY(var(--timeline-progress, 0)); transform-origin: top; }
.site-timeline li { position: relative; display: grid; gap: 7px; padding: 0 0 36px; }
.site-timeline li::before { content: ""; position: absolute; top: 6px; left: -34px; width: 15px; aspect-ratio: 1; border-radius: 50%; background: var(--ink); border: 3px solid var(--lime); z-index: 1; }
.site-timeline li strong { font-size: 24px; line-height: 1; font-weight: 800; }
.site-timeline li span { color: var(--text); font-size: 13px; max-width: 290px; }

.site-news-grid { display: flex; gap: 16px; overflow-x: auto; scroll-snap-type: x mandatory; padding: 4px 2px 18px; }
.site-news-card { flex: 0 0 min(82vw, 350px); scroll-snap-align: start; border: 1px solid var(--line); border-radius: var(--radius); overflow: hidden; box-shadow: 0 8px 20px rgb(22 61 74 / .055); }
.site-news-image { position: relative; aspect-ratio: 1.35; background: var(--paper); }
.site-news-image img { width: 100%; height: 100%; object-fit: cover; }
.site-news-date { position: absolute; top: 13px; left: 13px; display: grid; place-content: center; width: 54px; height: 58px; background: white; border-radius: 7px; color: var(--ink); text-align: center; font-size: 10px; line-height: 1; }
.site-news-date strong { font-size: 23px; font-weight: 800; }
.site-news-copy { padding: 21px; }
.site-news-copy .eyebrow { color: var(--lime-text); font-size: 13px; }
.site-news-copy h3 { font-size: 19px; min-height: 2.4em; }
.site-news-copy > p:not(.eyebrow), .site-news-copy details p { color: var(--text); font-size: 12px; margin-top: 12px; }
.site-news-copy summary { display: inline-flex; align-items: center; gap: 8px; margin-top: 17px; color: var(--lime-text); font-weight: 800; font-size: 11px; cursor: pointer; list-style: none; }
.site-news-copy summary::-webkit-details-marker { display: none; }
.site-news-copy summary:focus-visible { outline: 3px solid var(--lime-text); outline-offset: 4px; }

.site-team { background: var(--paper); }
.site-team-grid { display: grid; gap: 40px; }
.site-team-grid > div:first-child { max-width: 640px; }
.site-team-grid .button { margin-top: 28px; }
.site-benefits { display: grid; gap: 12px; }
.site-benefits article { padding: 20px; background: white; border-radius: 14px; }
.site-benefits svg { color: var(--lime-text); width: 25px; height: 25px; margin-bottom: 10px; }
.site-benefits h3 { margin-bottom: 7px; }
.site-benefits p { color: var(--text); font-size: 12px; }

.site-contact-grid { display: grid; gap: 45px; }
.site-contact-phone { display: flex; align-items: center; gap: 10px; margin-top: 28px; font-size: clamp(28px, 5vw, 47px); font-weight: 800; letter-spacing: -.04em; }
.site-contact-mail { display: inline-block; margin-top: 7px; color: var(--lime-text); font-size: 14px; font-weight: 700; }
.site-contact-side { align-self: end; padding: 25px; border: 1px solid var(--line); border-radius: var(--radius); }
.site-contact-side > p:first-child { color: var(--ink); font-weight: 800; }
.site-socials { display: flex; align-items: center; gap: 9px; margin-block: 15px 22px; }
.site-socials a { display: grid !important; place-items: center; width: 46px; height: 46px; margin: 0 !important; border-radius: 50%; background: var(--paper); color: var(--ink); }
.site-socials a:hover { background: var(--lime); color: var(--ink); }
.site-final-wrap { padding-bottom: 90px; }
.site-final-cta { border-radius: var(--radius); }
.site-final-cta .actions { display: grid; justify-items: start; }
.site-final-login { display: inline-flex; align-items: center; gap: 7px; color: var(--on-ink-muted); font-size: 12px; }
.site-final-login:hover { color: var(--lime); }
.site-footer .footer-grid a:not(.site-socials a) { width: max-content; }
.site-footer .footer-grid a svg { display: inline; vertical-align: middle; }
.site-footer { padding-top: 30px; }
.site-footer .footer-grid { gap: 22px 28px; padding-bottom: 24px; }
.site-footer .footer-logo { margin-bottom: 12px; }
.site-footer .footer-grid h3 { margin-bottom: 12px; }
.site-footer .footer-grid p { margin-block: 8px; }
.site-footer .footer-grid a { margin-block: 6px; }
.site-footer .footer-bottom { align-items: center; flex-wrap: wrap; gap: 12px 20px; padding-block: 12px; font-size: 13px; }
.site-footer-social { display: flex; align-items: center; gap: 10px; }
.site-footer .site-socials { margin: 0; }
.site-footer .site-socials a { width: 36px; height: 36px; }
.site-footer .footer-bottom > .text-link { display: inline-flex; align-items: center; gap: 6px; }
@media (max-width: 767px) {
  .site-footer { padding-top: 24px; }
  .site-footer .footer-grid { gap: 20px 16px; padding-bottom: 20px; }
  .site-footer .footer-logo { width: 150px; margin-bottom: 10px; }
  .site-footer .footer-grid a:not(.site-socials a) { width: fit-content; max-width: 100%; overflow-wrap: anywhere; }
  .site-footer .footer-bottom { gap: 12px 18px; }
  .site-footer .site-socials a { width: 44px; height: 44px; }
  .site-footer .footer-bottom > .text-link { min-height: 44px; }
}

.site-catalog-intro { padding: 100px 0 36px; background: var(--ink); color: white; }
.site-catalog-intro .eyebrow { color: var(--lime); }
.site-catalog-intro h1 { max-width: 820px; font-size: clamp(30px, 3.4vw, 46px); font-weight: 800; line-height: 1.02; letter-spacing: -.05em; }
.site-catalog-intro p:not(.eyebrow) { max-width: 640px; margin-block: 12px 0; color: var(--on-ink-muted); font-size: 15px; }
