.site-milestones-rail button { position: relative; flex: 0 0 84px; display: flex; flex-direction: column; align-items: center; gap: 8px; padding: 12px 4px 6px; border: 0; background: none; color: var(--muted); font: inherit; font-size: 14px; font-weight: 800; font-variant-numeric: tabular-nums; cursor: pointer; transition: color var(--dur-base) ease; }
