.site-milestones-rail button span { position: relative; width: 14px; height: 14px; border: 3px solid white; border-radius: 50%; background: #b9c2c4; box-shadow: 0 0 0 2px #b9c2c4; transition: background-color var(--dur-base) ease, box-shadow var(--dur-base) ease, scale var(--dur-base) var(--ease-out); }
.site-milestones-rail button:hover { color: var(--ink); }
.site-milestones-rail button:focus-visible { outline: none; }
.site-milestones-rail button:focus-visible span { box-shadow: 0 0 0 3px var(--ink-deep), 0 0 0 6px var(--lime); }
.site-milestones-rail button[aria-selected="true"] { color: var(--ink); }
.site-milestones-rail button[aria-selected="true"] span { background: var(--lime); box-shadow: 0 0 0 3px var(--ink); scale: 1.15; }
.site-milestones-panel { position: relative; display: grid; gap: 12px; min-height: 220px; align-content: center; margin-top: 18px; padding: clamp(24px, 4vw, 40px); border: 1px solid var(--line); border-top: 5px solid var(--lime); border-radius: 0 0 var(--radius) var(--radius); background: var(--paper); animation: site-milestone-in 380ms var(--ease-out) both; }
.site-milestones-panel time { color: var(--ink); font-size: clamp(40px, 7vw, 68px); font-weight: 850; letter-spacing: -.06em; line-height: .9; }
.site-milestones-panel h3 { font-size: clamp(19px, 2vw, 24px); font-weight: 800; }
.site-milestones-panel p { max-width: 62ch; margin-top: 8px; color: var(--text); line-height: 1.65; }
.site-milestones-count { position: absolute; top: 14px; right: 18px; color: #8c9799; font-size: 11px; font-weight: 800; letter-spacing: .16em; }
@keyframes site-milestone-in { from { opacity: 0; transform: translateY(8px); } }
@media (prefers-reduced-motion: reduce) { .site-milestones-panel { animation: none; } }
@media (min-width: 768px) {
  .site-milestones-nav { gap: 16px; }
  .site-milestones-rail button { flex-basis: 108px; }
  .site-milestones-panel { grid-template-columns: minmax(150px, .32fr) minmax(0, 1fr); align-items: center; gap: clamp(32px, 5vw, 72px); }
}

/* Puntos de venta en /contacto, como el StoreLocator de Importadora: filtros, listado y mapa en un solo panel. */
.site-locator { padding-block: clamp(36px, 4vw, 56px); border-top: 1px solid var(--line); background: white; }
.site-locator .site-section-heading { margin-bottom: clamp(22px, 2.5vw, 32px); }
.site-locator .site-section-heading h2 { font-size: clamp(26px, 3.6vw, 40px); }
.site-locator .contact-locator { margin-top: 0; }
.site-locator .contact-demo-note { margin-bottom: 12px; }
.site-locator .contact-filters { margin-top: 0; padding: 16px; border: 1px solid var(--line); border-radius: var(--radius) var(--radius) 0 0; }
.site-locator .contact-location-message { margin: 0; padding: 12px 16px; border-inline: 1px solid var(--line); background: color-mix(in srgb, var(--lime) 12%, white); }
.site-locator .contact-locator-layout { gap: 0; margin-top: 0; border: 1px solid var(--line); border-top: 0; border-radius: 0 0 var(--radius) var(--radius); overflow: clip; }
.site-locator .contact-result-count { position: relative; margin: 0; padding: 14px 20px; background: var(--ink); color: white; font-size: 13px; font-variant-numeric: tabular-nums; }
.site-locator .contact-store-list { max-height: 374px; padding: 12px; }
.site-locator .contact-map-wrap { position: relative; top: auto; min-height: 420px; border-radius: 0; }
.site-locator .contact-map { height: 420px; }
@media (max-width: 900px) {
  .site-locator .contact-map-wrap { order: 0; min-height: 300px; }
  .site-locator .contact-map { height: 300px; }
}
@media (max-width: 759.98px) {
  .site-locator .site-section-heading { display: grid; gap: 12px; }
  .site-locator .contact-filters { grid-template-columns: 1fr; }
  .site-locator .contact-filters-toggle { display: flex; align-items: center; justify-content: space-between; min-height: 44px; padding: 10px 14px; border: 1px solid var(--line); border-radius: 10px; background: white; color: var(--ink); font: inherit; font-size: 14px; font-weight: 700; cursor: pointer; }
  .site-locator .contact-filters-toggle::after, .site-locator .contact-list-toggle::after { content: ""; width: 8px; height: 8px; border: solid currentColor; border-width: 0 2px 2px 0; transform: translateY(-25%) rotate(45deg); }
  .site-locator .contact-filters-toggle[aria-expanded="true"]::after, .site-locator .contact-list-toggle[aria-expanded="true"]::after { transform: translateY(25%) rotate(-135deg); }
  .site-locator .contact-filter-panel { display: grid; gap: 14px; }
  .site-locator .contact-filter-panel:not(.is-open) { display: none; }
  .site-locator .contact-list-toggle { display: flex; align-items: center; justify-content: flex-end; position: absolute; inset: 0; padding-right: 22px; border: 0; background: transparent; color: white; cursor: pointer; }
  .site-locator .contact-list-toggle:focus-visible { outline: 2px solid white; outline-offset: -4px; }
  .site-locator .contact-store-list:not(.is-open) { display: none; }
}
